#!/bin/sh
# Generated by matugen -- do not edit by hand.
# Invoked from ~/.aerospace.toml's after-startup-command, and re-invoked by
# matugen's post_hook on every theme change. `borders` live-updates an
# already-running instance instead of needing a restart.

# If borders is already running this just sends it an update and returns
# immediately. If it's not running yet, this call itself would block in the
# foreground forever, so we always background+disown it.
borders active_color=0xff{{colors.primary.default.hex_stripped}} \
        inactive_color=0xff{{colors.outline_variant.default.hex_stripped}} \
        width=10.0 &
disown
